using NUnit.Framework;
using LastRail.Battle;
using System;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using Newtonsoft.Json.Linq;
using LastRail.Auth;
using LastRail.Run;
namespace LastRail.Tests.EditMode {
 public sealed class BNamedEffectiveSourceTests {
  [TestCase("LastRail.Battle.BNamedEffectiveSource")][TestCase("LastRail.Battle.BNamedEffectiveSourceOwner")][TestCase("LastRail.Run.BNamedEffectiveSourceHttpClient")]
  public void ExplicitEffectiveConsumerMustExist(string name){Assert.NotNull(typeof(BDirectAttackInput).Assembly.GetType(name));}
  internal static JObject Packet(bool local=true)=>(JObject)JObject.Parse(File.ReadAllText("D:/Project/LASTRAIL/QA/CommanderS1-20260922/combat-b-named-effective-source-"+(local?"local-refit":"public")+"-sample-20261004.json"))["packet"];
  internal static BNamedEffectiveSource Read(JObject p=null){p=p??Packet();return BNamedEffectiveSource.Read(p,p,(string)p["packetHash"],"a");}
  [TestCase(true)][TestCase(false)] public void OriginalSuppliedSamplesKeepStatusesNullAndOriginalBase(bool local){var p=Packet(local);var s=Read(p);Assert.AreEqual(local?"ORIGINAL_PERSISTED_PROVIDER_BOUND":"OPERATING_PROVIDER_UNAVAILABLE",s.ProviderStatus);Assert.IsTrue(JToken.DeepEquals(p,s.Capture()));Assert.AreEqual(1400,(int)s.RequirePredepartureBase().Actor("op_kyle")["permanentStats"]["maxHp"]);Assert.AreEqual(JTokenType.Null,s.Capture()["actors"][0]["effectiveStats"].Type);Assert.IsFalse((bool)s.Capture()["applicability"]["equipment"]["verifiedEmptyRunInventory"]);s.Capture()["actors"][0]["resolvedPredepartureStats"]["maxHp"]=1;Assert.AreEqual(1400,(int)s.Capture()["actors"][0]["resolvedPredepartureStats"]["maxHp"]);}
  [TestCase("owner")][TestCase("stale")][TestCase("effect")][TestCase("empty")][TestCase("base")][TestCase("unknown")]
  public void WrongOwnerStaleOrMutatedSourceCannotBeRehashedIntoApproval(string fault){var original=Packet();var p=(JObject)original.DeepClone();string account="a",effect=null;if(fault=="owner")account="foreign";if(fault=="stale")effect=new string('0',64);if(fault=="effect")p["effectSourceHash"]=new string('0',64);if(fault=="empty")p["applicability"]["equipment"]["verifiedEmptyRunInventory"]=true;if(fault=="base")p["actors"][0]["resolvedPredepartureStats"]["maxHp"]=999999;if(fault=="unknown")p["extra"]=1;Assert.Throws<ArgumentException>(()=>BNamedEffectiveSource.Read(p,original,(string)original["packetHash"],account,effect));}
  static void Rehash(JObject p,string key){p.Remove(key);p[key]=BDirectAttackInput.Digest(p).Substring(7);}
  internal static JObject UnsupportedContractFixture(){var p=Packet();p["applicability"]["commander"]["status"]="UNSUPPORTED_SELECTED_EFFECTS";p["applicability"]["commander"]["errorCode"]="commander_definition_unsupported";p["effectSourceHash"]=BDirectAttackInput.Digest(p["applicability"]).Substring(7);foreach(var a in p["actors"]){a["resolvedPredepartureStats"]=JValue.CreateNull();((JArray)a["missing"]).Insert(0,"ORIGINAL_COMMANDER_EFFECT_EXECUTION_OWNER");}Rehash(p,"packetHash");return p;}
  [Test] public void UnsupportedCommanderRetainsLineageAndCannotExecuteBaseProof(){var s=Read(UnsupportedContractFixture());Assert.AreEqual("UNSUPPORTED_SELECTED_EFFECTS",s.CommanderStatus);Assert.AreEqual(JTokenType.Null,s.Capture()["actors"][0]["resolvedPredepartureStats"].Type);Assert.Throws<ArgumentException>(()=>s.RequirePredepartureBase());}
  [Test] public async Task RefreshRebindUnbindDisposeRejectLatePublicationAndKeepOldSnapshot(){var owner=new BNamedEffectiveSourceOwner("a");int oldCalls=0,newCalls=0;owner.Bind(s=>oldCalls++);var pending=new TaskCompletionSource<BNamedEffectiveSource>();var stale=owner.RefreshAsync(()=>pending.Task);owner.Bind(s=>newCalls++);pending.SetResult(Read());Assert.IsFalse(await stale);Assert.AreEqual(0,oldCalls);Assert.AreEqual(0,newCalls);Assert.IsTrue(await owner.RefreshAsync(()=>Task.FromResult(Read())));var original=owner.Current;Assert.AreEqual(1,newCalls);Assert.IsTrue(await owner.RefreshAsync(()=>Task.FromResult(Read(UnsupportedContractFixture()))));Assert.AreNotEqual(original.EffectSourceHash,owner.Current.EffectSourceHash);Assert.AreEqual("VERIFIED_NO_ACTIVE_EFFECTS",original.CommanderStatus);pending=new TaskCompletionSource<BNamedEffectiveSource>();stale=owner.RefreshAsync(()=>pending.Task);owner.Unbind();pending.SetResult(Read());Assert.IsFalse(await stale);Assert.AreEqual(2,newCalls);owner.Bind(s=>newCalls++);pending=new TaskCompletionSource<BNamedEffectiveSource>();stale=owner.RefreshAsync(()=>pending.Task);owner.Dispose();pending.SetResult(Read());Assert.IsFalse(await stale);Assert.AreEqual(2,newCalls);Assert.Throws<ObjectDisposedException>(()=>owner.Bind(s=>{}));}
  sealed class Transport:IGameApiAuthenticatedHttpTransport {public RunApiHttpRequest Request;public GameApiAccessToken Token;public GameApiAuthenticatedHttpResult Result;public Task<GameApiAuthenticatedHttpResult> SendAsync(RunApiHttpRequest r,GameApiAccessToken t){Request=r;Token=t;return Task.FromResult(Result);}}
  [Test] public async Task NewApiAuthenticatesAndChecksExactEffectHashAndOriginalPublicStatus(){var p=Packet(false);var t=new Transport{Result=GameApiAuthenticatedHttpResult.Succeeded(RunApiHttpResponse.Success(200,p.ToString(),new[]{new RunApiHttpHeader("ETag",(string)p["packetHash"])}))};var token=new GameApiAccessToken("lst1.local-test-only");var s=await new BNamedEffectiveSourceHttpClient(t).CaptureAsync(new[]{"op_kyle","op_sable"},1,1,token,"a",(string)p["effectSourceHash"]);Assert.AreSame(token,t.Token);Assert.AreEqual("/v1/combat/b-named-effective-source",t.Request.EndpointPath);Assert.AreEqual(BNamedEffectiveSource.Version,t.Request.Headers.Single(h=>h.Name=="X-B-Named-Effective-Version").Value);Assert.AreEqual(4,JObject.Parse(t.Request.BodyJson).Count);Assert.AreEqual("OPERATING_PROVIDER_UNAVAILABLE",s.ProviderStatus);}
  [Test] public void AuthFailureAndWrongEtagNeverCreateEffectiveSource(){var t=new Transport{Result=GameApiAuthenticatedHttpResult.AuthRequired(RunApiHttpResponse.Success(401,"{}"),"expired",null)};var client=new BNamedEffectiveSourceHttpClient(t);Assert.ThrowsAsync<InvalidOperationException>(async()=>await client.CaptureAsync(new[]{"op_sable"},1,1,new GameApiAccessToken("lst1.local-test-only"),"a"));var p=Packet();t.Result=GameApiAuthenticatedHttpResult.Succeeded(RunApiHttpResponse.Success(200,p.ToString(),new[]{new RunApiHttpHeader("ETag",new string('0',64))}));Assert.ThrowsAsync<ArgumentException>(async()=>await client.CaptureAsync(new[]{"op_kyle","op_sable"},1,1,new GameApiAccessToken("lst1.local-test-only"),"a"));}
  [Test] public void VerifiedBaseProofConnectsExistingNativeWithoutApplyingAnyEffect(){var effective=Read();var baseOnly=BNamedOperatorSourceTests.Native();var supplied=BNamedOperatorSourceTests.Native(effective.RequirePredepartureBase());Assert.AreEqual(baseOnly.adapter.Input.OriginalHash,supplied.adapter.Input.OriginalHash);var g=BOrdinaryGeometryTests.Geometry(supplied.binding);var native=supplied.adapter.CreateRuntime(supplied.binding,g,10000);Assert.AreEqual(1400,native.Hp("op_kyle"));Assert.AreEqual(1600,native.Hp("op_sable"));Assert.IsFalse(native.Capture()["state"]==null);Assert.IsTrue(effective.Capture()["actors"].All(a=>(long)a["modifierApplications"]==0&&a["effectiveStats"].Type==JTokenType.Null));}
  [Test] public async Task ConcurrentRefreshOnlyPublishesLatestAndFailurePreservesCurrent(){using(var owner=new BNamedEffectiveSourceOwner("a")){int calls=0;owner.Bind(s=>calls++);var late=new TaskCompletionSource<BNamedEffectiveSource>();var old=owner.RefreshAsync(()=>late.Task);Assert.IsTrue(await owner.RefreshAsync(()=>Task.FromResult(Read())));var current=owner.Current;late.SetResult(Read(UnsupportedContractFixture()));Assert.IsFalse(await old);Assert.AreEqual(1,calls);Assert.AreSame(current,owner.Current);Assert.ThrowsAsync<InvalidOperationException>(async()=>await owner.RefreshAsync(()=>Task.FromException<BNamedEffectiveSource>(new InvalidOperationException("source unavailable"))));Assert.AreSame(current,owner.Current);Assert.AreEqual(1,calls);}}
  [Test] public void MissingOriginalRuntimeOwnerIsNeverDefaultedByRehashedTrustedContractFixture(){var p=Packet();p["actors"][0]["effectiveStats"]=p["actors"][0]["resolvedPredepartureStats"].DeepClone();Rehash(p,"packetHash");Assert.Throws<ArgumentException>(()=>Read(p));}
  [Test] public void UnsupportedCommanderSnapshotMustRemainNull(){var p=UnsupportedContractFixture();p["applicability"]["commander"]["snapshot"]=new JObject{["ranks"]=new JObject()};p["effectSourceHash"]=BDirectAttackInput.Digest(p["applicability"]).Substring(7);Rehash(p,"packetHash");Assert.Throws<ArgumentException>(()=>Read(p));}
 }
}
